        // cheque cancel only if BOTH payment and reject are cheque-type
        if (@VW_GPT_SUB_PAYMENTTYPE == 2 && nextPT == 2) {
            if (@VW_GPT_SUB_AMOUNT == nextAmt &&
                @VW_GPT_SUB_CHEQUENUMBER == nextChq)
                return true;
        }
        else if (@VW_GPT_SUB_PAYMENTTYPE != 2 && nextPT != 2) {
            if (@VW_GPT_SUB_AMOUNT == nextAmt)
                return true;
        }
    } 
    else return false;
}

else return false;

